<template>
  <div class="account-panel">
    <q-list bordered separator>
      <q-item v-for="account in accounts" :key="account.internalId || account.id" clickable :active="selected===accountRef(account)" active-class="account-active" @click="select(account)">
        <q-item-section avatar><q-avatar color="primary" text-color="white"><span v-if="account.profile?.skin?.url" class="account-face" :style="skinFaceStyle(account.profile.skin.url)" aria-hidden="true"></span><span v-else>{{ (account.profileName||account.displayName||'?').slice(0,1).toUpperCase() }}</span></q-avatar></q-item-section>
        <q-item-section><q-item-label>{{ account.profileName || account.displayName || t('neo.auto2.k2980233f7d') }} <q-badge v-if="account.default" color="positive">{{ t('neo.auto2.kc8d09cf955') }}</q-badge><q-badge v-if="account.cacheAvailable" color="info">{{ t('neo.auto2.kd59b2c34aa') }}</q-badge><q-badge v-else-if="account.cacheState==='not-cached'" color="grey">{{ t('neo.auto2.k2f52e78e73') }}</q-badge></q-item-label><q-item-label caption>{{ accountTypeLabel(account) }} · {{ accountStateLabel(account) }} · {{ t('neo.extra.cache') }}: {{ cacheStateLabel(account) }}</q-item-label></q-item-section>
        <q-item-section side><div class="row q-gutter-xs"><q-btn flat :label="t('neo.auto2.k8a0c839791')" :disable="busy" @click.stop="move(account,-1)"/><q-btn flat :label="t('neo.auto2.k05c46fa3b7')" :disable="busy" @click.stop="move(account,1)"/><q-btn flat :label="t('neo.auto2.kc8d09cf955')" :disable="busy" @click.stop="execute('account.set-default',{account:accountRef(account)})"/><q-btn flat color="negative" :label="t('neo.auto2.k2f752c005e')" :disable="busy" @click.stop="remove(account)"/></div></q-item-section>
      </q-item>
    </q-list>
    <div v-if="profile" class="q-mt-lg">
      <q-card class="profile-card"><q-card-section><div class="text-h6">{{ profile.name }}</div><div class="text-caption text-grey-5">{{ profile.state }} · {{ profile.canPlayMinecraft ? t('neo.auto2.k9b0f2814f0') : t('neo.auto2.k6f206917cf') }}</div></q-card-section>
        <q-card-section><div class="row q-col-gutter-lg"><div class="col-12 col-md-5"><q-img v-if="profile.skin?.url" :src="profile.skin.url" ratio="1" fit="contain" class="skin-preview"/><div v-else class="skin-empty">{{ t('neo.auto2.k33a99d8c22') }}</div><div class="row q-gutter-sm q-mt-md"><q-input class="col" dark outlined v-model="skinPath" :label="t('neo.auto2.k43c5578488')"/><q-btn :label="t('neo.auto2.k60e2bcad85')" :disable="busy || !skinPath" @click="installSkin"/></div><div class="row q-gutter-sm q-mt-sm"><q-select class="col" dark outlined v-model="skinName" :options="skinNames" :label="t('neo.auto2.k0c93f67140')"/><q-select class="col" dark outlined v-model="variant" :options="['classic','slim']" :label="t('neo.auto2.k98fd0cbd9c')"/><q-btn :label="t('neo.auto2.kb7ff9a5d59')" :disable="busy || !skinName" @click="uploadSkin"/></div><q-btn flat color="negative" :label="t('neo.auto2.kb77345b22c')" :disable="busy" class="q-mt-sm" @click="resetSkin"/></div>
          <div class="col-12 col-md-7"><div class="text-subtitle1">{{ t('neo.auto2.ke79e543b08') }}</div><q-list bordered separator class="q-mt-sm"><q-item v-for="cape in profile.capes||[]" :key="cape.id" clickable @click="selectCape(cape)"><q-item-section>{{ cape.alias || cape.id }}</q-item-section><q-item-section side><q-icon :name="cape.current?'check_circle':'radio_button_unchecked'" :color="cape.current?'positive':'grey'"/></q-item-section></q-item></q-list><q-btn flat :label="t('neo.auto2.k284460ac4a')" :disable="busy" class="q-mt-sm" @click="chooseCape('')"/><div class="text-subtitle1 q-mt-lg">{{ t('neo.auto2.k7aa619777a') }}</div><q-list bordered separator><q-item v-for="skin in skins" :key="skin.name || skin.path"><q-item-section>{{ skin.name || skin.path }}</q-item-section><q-item-section side><q-btn flat color="negative" :label="t('neo.auto2.k3755f56f2f')" :disable="busy" @click="deleteSkin(skin)"/></q-item-section></q-item></q-list></div></div></q-card-section>
      </q-card>
      <q-card v-if="selectedAccount" class="config-card q-mt-md"><q-card-section><div class="text-subtitle1">{{ t('neo.auto2.kb2f403f0a0') }}</div><div class="text-caption text-grey-5">{{ t('neo.auto2.kef0c976f48') }}</div></q-card-section><q-card-section v-if="selectedAccount.type==='yggdrasil'"><div class="row q-col-gutter-sm"><q-input class="col-12 col-md-6" dark outlined v-model="config.authUrl" :label="t('neo.auto2.kdca415e711')"/><q-input class="col-12 col-md-6" dark outlined v-model="config.sessionUrl" :label="t('neo.auto2.kb3b714ae4b')"/><q-input class="col-12 col-md-6" dark outlined v-model="config.sourceName" :label="t('neo.auto2.kd82acb1b50')"/><q-select class="col-12 col-md-6" dark outlined v-model="config.tokenType" :options="['Standard','OAuth']" :label="t('neo.auto2.ka097cdf15d')"/><q-input class="col-12 col-md-6" dark outlined v-model="config.authenticateEndpoint" label="Authenticate endpoint"/><q-input class="col-12 col-md-6" dark outlined v-model="config.refreshEndpoint" label="Refresh endpoint"/><q-input class="col-12 col-md-6" dark outlined v-model="config.validateEndpoint" label="Validate endpoint"/><q-input class="col-12 col-md-6" dark outlined v-model="config.profileEndpoint" label="Profile endpoint"/><q-input class="col-12 col-md-6" dark outlined v-model="config.oauthTokenEndpoint" label="OAuth token endpoint"/></div><q-btn color="primary" class="q-mt-md" :disable="busy" :label="t('neo.auto2.k75a04f822b')" @click="saveConfig"/></q-card-section><q-card-section v-else-if="selectedAccount.type==='unified-pass'"><div class="row q-col-gutter-sm"><q-input class="col-12 col-md-6" dark outlined v-model="config.serverId" label="UnifiedPass Server ID"/><q-input class="col-12 col-md-6" dark outlined v-model="config.baseUrl" label="API Base URL"/></div><q-btn color="primary" class="q-mt-md" :disable="busy" :label="t('neo.auto2.k75a04f822b')" @click="saveConfig"/></q-card-section></q-card>
    </div>
    <q-banner v-if="error" class="bg-red-9 q-mt-md">{{ error }}</q-banner>
  </div>
</template>
<script setup lang="ts">
import { useI18n } from "vue-i18n";
const { t } = useI18n();
import { ref } from 'vue';
const props=defineProps<{accounts:any[];busy:boolean;execute:(op:string,p?:Record<string,unknown>)=>Promise<any>}>();
const emit=defineEmits<{changed:[]}>();
const selected=ref(''),selectedAccount=ref<any>(null),profile=ref<any>(null),skins=ref<any[]>([]),skinPath=ref(''),skinName=ref(''),variant=ref('classic'),error=ref('');
const config=ref<any>({authUrl:'',sessionUrl:'',sourceName:'',tokenType:'Standard',authenticateEndpoint:'',refreshEndpoint:'',validateEndpoint:'',profileEndpoint:'',oauthTokenEndpoint:'',serverId:'',baseUrl:''});
const skinNames=ref<any[]>([]);
function accountRef(account:any){return String(account?.internalId || account?.id || account?.profileName || '');}
function accountTypeLabel(account:any){const type=String(account?.type||'').toLowerCase();if(type.includes('msa')||type.includes('microsoft'))return t('neo.auto2.k138a037eac');if(type.includes('ygg')){const server=account?.yggdrasil?.displayName||account?.yggdrasil?.sourceName||account?.authServer?.displayName||account?.authServerName||t('neo.auto2.k5bbd1b1fdd');return `${t('neo.extra.thirdPartyAuth')} · ${server}`;}if(type.includes('unified')){const server=account?.unifiedPass?.displayName||account?.unifiedPass?.serverName||account?.unifiedPass?.serverId||account?.authServer?.displayName||account?.authServerName||t('neo.extra.unifiedPass');return `${t('neo.extra.unifiedPass')} · ${server}`;}return t('neo.auto2.k0c85a32b2c');}
function accountStateLabel(account:any){const state=String(account?.stateName||'').toLowerCase();return ({online:t('neo.auto2.k0373ff9231'),working:t('neo.auto2.k521a54bb02'),offline:t('neo.auto2.k211357d22f'),expired:t('neo.auto2.k1354374f76'),errored:t('neo.auto2.kb859c7be75'),disabled:t('neo.auto2.k0fe5a98e9f'),gone:t('neo.auto2.ka09345748d'),unchecked:t('neo.auto2.ked9ec8188c')} as any)[state] || (account?.stateName || t('neo.auto2.ked9ec8188c'));}
function cacheStateLabel(account:any){const state=String(account?.cacheState||'unknown');return ({cached:t('neo.auto2.kd59b2c34aa'),'not-cached':t('neo.auto2.k2f52e78e73'),unknown:t('neo.auto2.k9908c922f2')} as any)[state] || t('neo.auto2.kd9c32a4c3d');}
function skinFaceStyle(url:string){return {backgroundImage:`url("${String(url).replace(/"/g,'%22')}")`};}
async function attempt(action:()=>Promise<any>){error.value='';try{return await action();}catch(e){error.value=String(e);}}
async function select(account:any){const reference=accountRef(account);selected.value=reference;selectedAccount.value=account;config.value={authUrl:account.yggdrasil?.authUrl||'',sessionUrl:account.yggdrasil?.sessionUrl||'',sourceName:account.yggdrasil?.sourceName||'',tokenType:account.yggdrasil?.tokenType||'Standard',authenticateEndpoint:account.yggdrasil?.authenticateEndpoint||'',refreshEndpoint:account.yggdrasil?.refreshEndpoint||'',validateEndpoint:account.yggdrasil?.validateEndpoint||'',profileEndpoint:account.yggdrasil?.profileEndpoint||'',oauthTokenEndpoint:account.yggdrasil?.oauthTokenEndpoint||'',serverId:account.unifiedPass?.serverId||'',baseUrl:account.unifiedPass?.baseUrl||''};await attempt(async()=>{profile.value=await props.execute('account.profile',{account:reference});skins.value=await props.execute('account.skin.list',{account:reference});skinNames.value=skins.value.map((s:any)=>s.name||s.path);});}
async function move(a:any,delta:number){await attempt(async()=>{await props.execute('account.move',{account:accountRef(a),delta});emit('changed');});}
async function remove(a:any){await attempt(async()=>{await props.execute('account.remove',{account:accountRef(a),confirm:true});profile.value=null;selected.value='';emit('changed');});}
async function installSkin(){await attempt(async()=>{await props.execute('account.skin.install',{account:selected.value,path:skinPath.value});skinPath.value='';await select({id:selected.value});});}
async function uploadSkin(){await attempt(async()=>{await props.execute('account.skin.upload',{account:selected.value,skin:skinName.value,variant:variant.value});await select({id:selected.value});});}
async function resetSkin(){await attempt(async()=>{await props.execute('account.skin.reset',{account:selected.value,confirm:true});await select({id:selected.value});});}
async function deleteSkin(s:any){await attempt(async()=>{await props.execute('account.skin.delete',{account:selected.value,skin:s.name||s.path,confirm:true});await select({id:selected.value});});}
async function chooseCape(cape:string){await attempt(async()=>{await props.execute('account.cape.select',{account:selected.value,cape});await select({id:selected.value});});}
function selectCape(cape:any){return chooseCape(cape.id);}
async function saveConfig(){await attempt(async()=>{const p:any={account:selected.value};if(selectedAccount.value?.type==='yggdrasil')Object.assign(p,{authUrl:config.value.authUrl,sessionUrl:config.value.sessionUrl,sourceName:config.value.sourceName,tokenType:config.value.tokenType,authenticateEndpoint:config.value.authenticateEndpoint,refreshEndpoint:config.value.refreshEndpoint,validateEndpoint:config.value.validateEndpoint,profileEndpoint:config.value.profileEndpoint,oauthTokenEndpoint:config.value.oauthTokenEndpoint});else Object.assign(p,{serverId:config.value.serverId,baseUrl:config.value.baseUrl});await props.execute('account.configure',p);emit('changed');});}
</script>
<style scoped>.account-panel{max-width:1100px}.account-face{display:block;width:100%;height:100%;border-radius:inherit;background-repeat:no-repeat;background-size:800% 800%;background-position:14.2857% 14.2857%;image-rendering:pixelated;image-rendering:crisp-edges}.skin-preview :deep(img){image-rendering:pixelated;image-rendering:crisp-edges}.profile-card{background:var(--neo-panel);border:1px solid var(--neo-border)}.skin-preview{max-width:320px;background:#101827;border-radius:14px}.skin-empty{height:260px;display:grid;place-items:center;background:#101827;border-radius:14px;color:var(--neo-muted)}.account-active{background:rgba(99,102,241,.18)}</style>
